<script lang="ts">
  import { onMount, tick } from 'svelte';
  import { uiText } from '../../ui/i18n.ts';
  import { game } from '../../../gameManager.js';
  import { setRocketCasinoOpen, setRocketCasinoClose } from '../../bridge/rocketCasinoModalBridge.js';
  import { wireRocketCasinoModalControls } from '../../ui/rocketDisplay.ts';
  import { rocket } from '../../stores/rocket.svelte.ts';
  import RocketCasinoHistory from './RocketCasinoHistory.svelte';
  import RocketCasinoAutoSpin from './RocketCasinoAutoSpin.svelte';

  let visible = $state(false);

  const trText = (key: string, fallback: string) =>
    uiText(`teamRocket.${key}`, fallback, {}, game);

  let casino = $derived(rocket.casinoModal);

  function open(): void {
    visible = true;
  }

  function close(): void {
    visible = false;
  }

  onMount(() => {
    setRocketCasinoOpen(open);
    setRocketCasinoClose(close);
    return () => {
      setRocketCasinoOpen(() => {});
      setRocketCasinoClose(() => {});
    };
  });

  $effect(() => {
    if (!visible || !game?.teamRocketState) return;
    void tick().then(() => {
      if (game) wireRocketCasinoModalControls(game);
    });
  });
</script>

<div
  id="rocketCasinoOverlay"
  class="stats-modal js-modal-overlay"
  class:show={visible}
  role="dialog"
  aria-modal="true"
  aria-hidden={!visible}
  data-action="closeRocketCasinoModal"
  data-action-self
>
  <div class="stats-content js-modal-content rocket-casino-modal-content" data-action="stopPropagation" data-action-stop>
    <div class="stats-header">
      <h2>{trText('casinoMachineTitle', 'Rocket Slot Machine')}</h2>
      <button class="stats-close js-close-modal" type="button" data-action="closeRocketCasinoModal">&times;</button>
    </div>
    <div class="rocket-casino-modal-grid">
      <div class="rocket-casino-main">
        <div class="slots-machine">
          <div class="slots-machine-screen" aria-hidden="false">
            <div class="rocket-casino-grid3x3" id="rocketCasinoGrid3x3">
              {#each [0, 1, 2] as row}
                {#each [0, 1, 2] as col}
                  <div class="rocket-casino-cell" id="rocketCasinoCell_{col}_{row}">
                    <div class="rocket-casino-cell-mask">?</div>
                  </div>
                {/each}
              {/each}
            </div>
          </div>
          <div class="slots-machine-scanlines" aria-hidden="true"></div>
          <img src="img/slots-machine.webp" class="slots-machine-frame" alt="">
          <button class="spin-btn" id="rocketCasinoSpinBtn" aria-label={trText('casinoSpinAria', 'Spin machine')}></button>
        </div>
      </div>
      <div class="rocket-casino-side">
        <div id="rocketCasinoModalRjText" class="tr-text-value rocket-casino-rj-display" style="margin-bottom:12px; position:relative;">
          {casino.rjLabel}
        </div>
        <RocketCasinoAutoSpin />
        <div id="rocketCasinoSidePane_history" class="rocket-casino-side-pane is-active">
          <h4 class="rocket-casino-side-heading tr-text-title">{trText('casinoHistoryTitle', 'History (last 10)')}</h4>
          <div id="rocketCasinoHistoryList" class="rocket-casino-history">
            <RocketCasinoHistory />
          </div>
        </div>
      </div>
    </div>
  </div>
</div>
